awk -F, 'BEGIN{OFS=","} 
NR==1 {print; next} 
{
    if ($2 ~ /^[0-9]{2}\/[0-9]{2}\/[0-9]{4}$/) {
        split($2, date_parts, "/")
        $2 = date_parts[3] "-" date_parts[2] "-" date_parts[1] "T00:00:00Z"
    }
    print
}' /data/csv/events_02.csv > /tmp/processed_csv/events_02_processed.csv

awk -F, 'BEGIN{OFS=","} 
NR==1 {print; next} 
{
    if ($2 ~ /^[0-9]{2}\/[0-9]{2}\/[0-9]{4}$/) {
        split($2, date_parts, "/")
        day = date_parts[1]
        month = date_parts[2] 
        year = date_parts[3]
        $2 = year "-" month "-" day "T00:00:00Z"
    }
    print
}' /data/csv/events_02.csv > /tmp/processed_csv/events_02_processed.csv

for file in /data/csv/events_*.csv; do
    basename=$(basename "$file" .csv)
    case "$basename" in
        "events_01")
            # Clean baseline - just convert timestamp format
            sed '1!s/T/ /g; 1!s/Z//g' "$file" > "/tmp/processed_csv/${basename}_final.csv"
            ;;
        "events_02")
            # Date conversion + timestamp format
            sed '1!s|\([0-9]\{2\}\)/\([0-9]\{2\}\)/\([0-9]\{4\}\)|2026-\2-\1 00:00:00|g' "$file" > "/tmp/processed_csv/${basename}_final.csv"
            ;;
        "events_03")
            # Handle nulls + timestamp format
            awk -F, 'BEGIN{OFS=","} 
            NR==1 {print; next}
            {
                if ($5 == "N/A" || $5 == "null" || $5 == "") {
                    $5 = "0"
                }
                gsub(/T/, " ", $2)
                gsub(/Z/, "", $2)
                print
            }' "$file" > "/tmp/processed_csv/${basename}_final.csv"
            ;;
        "events_04")
            # Remove duplicate header + timestamp format
            awk 'NR==1 {print; next} NR!=3 {gsub(/T/, " ", $2); gsub(/Z/, "", $2); print}' "$file" > "/tmp/processed_csv/${basename}_final.csv"
            ;;
        "events_05")
            # Remove trailing commas + timestamp format
            sed 's/,$//' "$file" | sed '1!s/T/ /g; 1!s/Z//g' > "/tmp/processed_csv/${basename}_final.csv"
            ;;
    esac
done
